#[test]
fn neon_is_present_and_assume_baseline_agrees() {
    // Mandatory on AArch64: detect() must succeed on every QEMU CPU model.
    assert!(Neon::detect().is_some());
    let t = Neon::assume_baseline();
    assert_eq!(
        t.add_i32x4([1, 2, 3, 4], [10, 20, 30, 40]),
        [11, 22, 33, 44]
    );
}

