#[test]
#[should_panic(expected = "even length")]
fn qasx_i16_slice_rejects_odd_length() {
    let t = Neon::assume_baseline();
    let mut out = [0i16; 3];
    t.qasx_i16_slice(&[1, 2, 3], &[4, 5, 6], &mut out);
}

// f16 <-> f32 conversions: `half` is the oracle (exact widening, RNE narrowing).
#[test]
fn cvt_f16_f32_round_trip_matches_half() {
    use half::f16;
    let t = Neon::assume_baseline();
    for r in 0..500u64 {
        let h: [u16; 4] =
            core::array::from_fn(|i| crate::aarch64::ops::macros::mix(r * 4 + i as u64) as u16);
        let wide = t.cvt_f16x4_to_f32x4(h);
        for i in 0..4 {
            let want = f16::from_bits(h[i]).to_f32();
            if want.is_nan() {
                assert!(wide[i].is_nan());
            } else {
                assert_eq!(wide[i].to_bits(), want.to_bits(), "{:#06x}", h[i]);
            }
        }
        let f: [f32; 4] = core::array::from_fn(|i| {
            f32::from_bits(crate::aarch64::ops::macros::mix(r * 4 + i as u64 + 99) as u32)
        });
        let narrow = t.cvt_f32x4_to_f16x4(f);
        for i in 0..4 {
            if f[i].is_nan() {
                assert!(f16::from_bits(narrow[i]).is_nan());
            } else {
                assert_eq!(narrow[i], f16::from_f32(f[i]).to_bits(), "{:e}", f[i]);
            }
        }
    }
    for len in [0usize, 1, 3, 4, 5, 7, 8, 9, 100] {
        let h: Vec<u16> = (0..len)
            .map(|i| f16::from_f32(i as f32 * 0.75 - 3.0).to_bits())
            .collect();
        let mut wide = vec![0f32; len];
        t.cvt_f16_to_f32_slice(&h, &mut wide);
        assert_eq!(
            wide,
            h.iter()
                .map(|&x| f16::from_bits(x).to_f32())
                .collect::<Vec<_>>(),
            "len={len}"
        );
        let mut back = vec![0u16; len];
        t.cvt_f32_to_f16_slice(&wide, &mut back);
        assert_eq!(back, h, "len={len}");
    }
}
